\label{def4.1} \cite{Ben-Tal 2009}
	A vector $\bm x$ is said to be the robust feasible solution of the uncertain problem \eqref{eq4.2a} if it satisfies the uncertain constraints for all realizations of the uncertain set $\mathscr{U}$, that is, if $\bm x$ satisfies
	\begin{align*}
	\begin{aligned}	
	c(\bm{x},\bm{u}) \leq 0, \quad \forall \bm u  \in \mathscr{U} 
	\end{aligned}
	\end{align*}

\label{def4.2} \cite{Ben-Tal 2009}
	For a given candidate solution $\bm{x}$, the robust value $\widehat{f}(\bm{x})$ of the objective in problem \eqref{eq4.2a} is the largest value of $f(\bm{x},\bm{u})$ over all realizations of the data from the uncertain set, that is
	\begin{align*}
	\begin{aligned}	
	\widehat{f}(\bm{x})= \max_{\bm u  \in \mathscr{U}} f(\bm{x},\bm{u})
	\end{aligned}
	\end{align*}

\label{def4.3} \cite{Ben-Tal 2009}
	The robust counterpart of the uncertain problem \eqref{eq4.2a} is the optimization problem 
	\begin{align}	
	\begin{aligned} \label{eq4.2b}
	& \min_{\bm x} && \left \{ \max_{\bm u \in \mathscr{U}}	f(\bm x, \bm u) \right \}\\
	&\text{s.t.:} && c(\bm x, \bm u) \leq \bm 0, \quad \forall \bm u  \in \mathscr{U}
	\end{aligned}
	\end{align}
	of minimizing the robust value of the objective over all robust feasible solutions to the uncertain problem.

\cite{Ben-Tal 1999} \label{thm4.0}
The robust counterpart of the uncertain problem \eqref{eq4.3} associated with the uncertain set $\mathscr{U}=\mathscr{U}_1 \times \mathscr{U}_2 \times \dots \times \mathscr{U}_m$, $\mathscr{U}_i$'s being given by \eqref{eq4.3aa}, is equivalent to the SDP problem
\begin{align}
\begin{aligned}	\label{eq4.3a}
&\min_x && \bm c ^\top \bm x  \\
&\textrm{w.r.t.} && \bm x \in \mathbb{R}^n, \ \lambda^1, \dots, \lambda^n \in \mathbb{R}\\
& \textrm{s.t.:}&& \begin{small}\left [\begin{array} {c|c c c c|c}
\gamma^{i(0)}+2 \bm x^\top\bm b^{i(0)}-\lambda^i & \dfrac{\gamma^{i(1)}}{2}+\bm x^\top \bm b^{i(1)}  & \dfrac{\gamma^{i(1)}}{2}+\bm x^\top \bm b^{i(1)} & \dots&\dfrac{\gamma^{i(1)}}{2}+\bm x^\top \bm b^{i(1)} & [\bm A^{i(1)}\bm x]^\top\\
\hline
\dfrac{\gamma^{i(1)}}{2}+\bm x^\top \bm b^{i(1)} & \lambda^i & & & & [\bm A^{i(1)}\bm x]^\top\\
\dfrac{\gamma^{i(2)}}{2}+\bm x^\top \bm b^{i(2)} & & \lambda^i & & & [\bm A^{i(2)}\bm x]^\top\\
\vdots & & &\ddots& & \vdots \\
\dfrac{\gamma^{i(k)}}{2}+\bm x^\top \bm b^{i(k)} & & & & \lambda^i & [\bm A^{i(k)}\bm x]^\top\\
\hline
\bm A^{i(0)}\bm x & \bm A^{i(1)}\bm x & \bm A^{i(2)}\bm x & \dots & \bm A^{i(k)}\bm x & I_{l_i}
\end{array}\right ]\end{small} \succeq 0\\
& && \text{for } i=1,2,\dots,m \text{ and $I_{l_i}$ is the identity matrix of order $l_i$}.
\end{aligned}
\end{align}

\cite{Ben-Tal 2009} \label{lemma4.1} Let $\bm A$, $\bm B$ be symmetric matrices of the same size such that, there exists $\bm{\bar z}$ satisfying $\bm{\bar z}^\top \bm A \bm{\bar z} \geq 0$. Then the implication
	\begin{align*}
	\begin{aligned}	
	\bm z^\top \bm A \bm z \geq 0 \implies \bm z^\top \bm B \bm z \geq 0
	\end{aligned}
	\end{align*}
	holds true if and only if
	\begin{align*}
	\begin{aligned}	
	\exists \  \lambda \geq 0 \quad : \quad \bm B \succeq \lambda \bm A
	\end{aligned}
	\end{align*}

\label{thm4.1}
Consider the uncertain Markowitz portfolio problem \eqref{eq4.5} under ellipsoidal uncertainty. The solution vector $\bm x$ to the problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the matrix 
\begin{scriptsize}
\begin{align*}
\begin{bmatrix} 
({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda
\end{bmatrix}
\end{align*}
\end{scriptsize} is positive semidefinite.

\label{thm4.2}
Consider the uncertain portfolio problem \eqref{eq4.5} under box uncertainty. The solution vector $\bm x$ to the problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the matrix 
\begin{scriptsize}
\begin{align*}
	\begin{bmatrix} 
		({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & \ ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& \ \dots  & \ ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(M)}}^\top\bm x)& \ \dots & \ ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
		({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & \ ({\bm{\mu}^{(1)}}^\top\bm x)^2 & \ \dots & \ ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(M)}}^\top\bm x)& \ \dots  & \ ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
		({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & \ ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& \ \dots  & \ ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(M)}}^\top\bm x) & \ \dots & \ ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
		\vdots & \ \vdots & \ \ddots & \ \vdots & \ \ddots & \ \vdots \\
		({\bm{\mu}^{(M)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & \ ({\bm{\mu}^{(M)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& \ \dots  & \ ({\bm{\mu}^{(M)}}^\top\bm x)^2+\lambda & \ \dots & \ ({\bm{\mu}^{(M)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
		\vdots & \ \vdots & \ \ddots & \ \vdots & \ \ddots & \ \vdots \\
		({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & \ ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& \ \dots  &\ ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(M)}}^\top\bm x) & \ \dots & \ ({\bm{\mu}^{(n)}}^\top\bm x)^2\\
	\end{bmatrix}
\end{align*}
\end{scriptsize} is positive semidefinite, where $M$ is the index of $\sup_j \zeta_j^2$.

\label{thm4.3}
Consider the uncertain portfolio problem \eqref{eq4.5} under polyhedral uncertainty. The solution vector $\bm x$ to the problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the matrix 
\begin{scriptsize}
\begin{align*}
\begin{bmatrix} 
({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda & ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda
\end{bmatrix}
\end{align*}
\end{scriptsize} is positive semidefinite.

\label{thm4.4}
Consider the uncertain portfolio problem \eqref{eq4.5} under the uncertainty set obtained from the combination of box and ellipsoidal uncertainty sets. Let the radii of the box and ellipsoidal sets are respectively $\delta_B$ and $\delta_E$. Then the solution vector $\bm x$ to this problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the following matrix inequalities hold:
\begin{tiny}
\begin{align*}
\begin{aligned}	
& \left \{ \begin{array}{ll}
\begin{bmatrix} 
(\sqrt n{\bm{\mu}^{(0)}}^\top\bm x)^2-n \tau^2-n\lambda & (\sqrt n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & (\sqrt n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & (\sqrt n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)(\sqrt n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(2)}}^\top\bm x)(\sqrt n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)(\sqrt n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda\\
\end{bmatrix} \succeq 0, &\mbox{ if } \min\left\{n\delta_B^2, \delta_E^2\right\}=n\delta_B^2\\
\\
\begin{bmatrix} 
({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda
\end{bmatrix} \succeq 0, &\mbox{ if } \min\left\{n\delta_B^2, \delta_E^2\right\}=\delta_E^2
\end{array} \right.
\end{aligned}
\end{align*} 
\end{tiny}

\label{thm4.5}
Consider the uncertain portfolio problem \eqref{eq4.5} under the uncertainty set obtained from the combination of box and polyhedral uncertainty sets. Let the radii of the box and polyhedral sets are respectively $\delta_B$ and $\delta_P$. Then the solution vector $\bm x$ to this problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the following matrix inequalities hold:
\begin{tiny}
\begin{align*}
\begin{aligned}	
& \left \{ \begin{array}{ll}
\begin{bmatrix} 
(n{\bm{\mu}^{(0)}}^\top\bm x)^2-n^2\tau^2-n^2\lambda & (n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & (n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & (n{\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)(n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
({\bm{\mu}^{(2)}}^\top\bm x)(n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda & ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)(n{\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda
\end{bmatrix} \succeq 0, &\mbox{ if } \min\left\{n\delta_B, \delta_P\right\}=n\delta_B\\
\\
\begin{bmatrix} 
({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda & ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)+\lambda\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)+\lambda &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x)+\lambda & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda\\
\end{bmatrix} \succeq 0, &\mbox{ if } \min\left\{n\delta_B, \delta_P\right\}=\delta_P
\end{array} \right.
\end{aligned}
\end{align*} 
\end{tiny}

\label{thm4.6}
Consider the uncertain portfolio problem \eqref{eq4.5} under the uncertainty set obtained from the combination of ellipsoidal and polyhedral uncertainty sets. Let the radii of the ellipsoidal and polyhedral sets are respectively $\delta_E$ and $\delta_P$. Then the solution vector $\bm x$ to this problem is feasible for the robust constraint in \eqref{eq4.5} if and only if there exists a $\lambda \geq 0$ such that the following matrix inequality hold:
\begin{align*}
\begin{scriptsize}
\begin{bmatrix} 
({\bm{\mu}^{(0)}}^\top\bm x)^2-\tau^2-\lambda & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)  & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(0)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(1)}}^\top\bm x)^2+\lambda & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(1)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x)& ({\bm{\mu}^{(2)}}^\top\bm x)^2+\lambda & \dots & ({\bm{\mu}^{(2)}}^\top\bm x)({\bm{\mu}^{(n)}}^\top\bm x)\\
\vdots & \vdots & \vdots & \ddots & \vdots \\
({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(0)}}^\top\bm x) & ({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(1)}}^\top\bm x) &({\bm{\mu}^{(n)}}^\top\bm x)({\bm{\mu}^{(2)}}^\top\bm x) & \dots & ({\bm{\mu}^{(n)}}^\top\bm x)^2+\lambda
\end{bmatrix}
\end{scriptsize} \succeq 0.
\end{align*}
